import type {
  TokenBudgetResult,
  WebGPUSmokeResult,
  WebGPUSpikeRequest,
  WebGPUSpikeResponse,
} from "./protocol";

function runWorkerRequest<T>(
  request: WebGPUSpikeRequest,
  expectedType: WebGPUSpikeResponse["type"],
): Promise<T> {
  const worker = new Worker(
    new URL("./webgpu-spike.worker.ts", import.meta.url),
    {
      type: "module",
    },
  );

  return new Promise<T>((resolve, reject) => {
    const timeout = window.setTimeout(() => {
      worker.terminate();
      reject(new Error("WebGPU feasibility worker timed out."));
    }, 120000);

    worker.onmessage = (event: MessageEvent<WebGPUSpikeResponse>) => {
      const response = event.data;
      if (response.requestId !== request.requestId) return;

      window.clearTimeout(timeout);
      worker.terminate();
      if (response.type === "error") {
        reject(new Error(response.message));
        return;
      }
      if (response.type !== expectedType) {
        reject(new Error(`Unexpected worker response: ${response.type}`));
        return;
      }
      resolve(response.result as T);
    };

    worker.onerror = (event) => {
      window.clearTimeout(timeout);
      worker.terminate();
      reject(new Error(event.message || "WebGPU feasibility worker crashed."));
    };

    worker.postMessage(request);
  });
}

function createRequestId(): string {
  return crypto.randomUUID();
}

export function runWebGPUSmoke(
  options: { allowWasmFallback?: boolean } = {},
): Promise<WebGPUSmokeResult> {
  return runWorkerRequest<WebGPUSmokeResult>(
    {
      type: "smoke",
      requestId: createRequestId(),
      ortWasmBaseUrl: new URL("ort/", document.baseURI).href,
      allowWasmFallback: options.allowWasmFallback === true,
    },
    "smoke_complete",
  );
}

export function measureTokenBudget(input: {
  modelId: string;
  revision: string;
  systemPrompt: string;
  tools: unknown[];
}): Promise<TokenBudgetResult> {
  return runWorkerRequest<TokenBudgetResult>(
    {
      type: "token_budget",
      requestId: createRequestId(),
      ...input,
    },
    "token_budget_complete",
  );
}
