import { Button, Text, makeStyles, tokens } from "@fluentui/react-components";
import { useMemo, useState } from "react";
import { getRuntimeConfigSync } from "../../lib/runtime-config";
import {
  measureTokenBudget,
  runWebGPUSmoke,
} from "../../lib/webgpu-spike/client";
import type {
  TokenBudgetResult,
  WebGPUSmokeResult,
} from "../../lib/webgpu-spike/protocol";
import {
  selectWebGPUTools,
  toWebGPUToolSchemas,
} from "../../lib/webgpu-spike/tool-policy";
import { buildSystemPrompt, getToolsForHost } from "./chat/chat-context";

const useStyles = makeStyles({
  root: {
    overflowY: "auto",
    padding: tokens.spacingHorizontalL,
    display: "flex",
    flexDirection: "column",
    gap: tokens.spacingVerticalL,
  },
  actions: {
    display: "flex",
    flexWrap: "wrap",
    gap: tokens.spacingHorizontalS,
  },
  output: {
    whiteSpace: "pre-wrap",
    fontFamily: tokens.fontFamilyMonospace,
    fontSize: tokens.fontSizeBase200,
    padding: tokens.spacingHorizontalM,
    border: `1px solid ${tokens.colorNeutralStroke1}`,
    backgroundColor: tokens.colorNeutralBackground2,
  },
});

export default function WebGPUSpikePage() {
  const styles = useStyles();
  const runtimeConfig = getRuntimeConfigSync();
  const runtime = runtimeConfig.webgpu;
  const tools = useMemo(
    () =>
      toWebGPUToolSchemas(
        selectWebGPUTools(
          getToolsForHost(),
          runtimeConfig.agentLoop.toolApprovalEnabled === true,
        ),
      ),
    [runtimeConfig.agentLoop.toolApprovalEnabled],
  );
  const systemPrompt = useMemo(() => buildSystemPrompt([]), []);
  const [smoke, setSmoke] = useState<WebGPUSmokeResult | null>(null);
  const [budget, setBudget] = useState<TokenBudgetResult | null>(null);
  const [status, setStatus] = useState("Ready to run.");
  const [busy, setBusy] = useState(false);

  const runSmoke = async (allowWasmFallback = false) => {
    setBusy(true);
    setStatus(
      allowWasmFallback
        ? "Running worker smoke test (WASM fallback permitted)..."
        : "Running module-worker and WebGPU compute smoke test...",
    );
    try {
      const result = await runWebGPUSmoke({ allowWasmFallback });
      setSmoke(result);
      setStatus(
        result.backend === "wasm"
          ? "Toolchain OK on WASM. WebGPU was NOT exercised — this proves bundling only, not inference viability."
          : result.usedFallbackAdapter
            ? "WebGPU smoke test passed on a SOFTWARE adapter. Timings are not representative."
            : "WebGPU smoke test passed.",
      );
    } catch (error) {
      setStatus(error instanceof Error ? error.message : String(error));
    } finally {
      setBusy(false);
    }
  };

  const runBudget = async () => {
    if (!runtime) return;
    setBusy(true);
    setStatus(
      "Downloading the pinned tokenizer and measuring exact prompt tokens...",
    );
    try {
      setBudget(
        await measureTokenBudget({
          modelId: runtime.modelId,
          revision: runtime.modelRevision,
          systemPrompt,
          tools,
        }),
      );
      setStatus("Tokenizer budget measurement completed.");
    } catch (error) {
      setStatus(error instanceof Error ? error.message : String(error));
    } finally {
      setBusy(false);
    }
  };

  return (
    <main className={styles.root}>
      <Text as="h1" size={600} weight="semibold">
        WebGPU embedded LLM feasibility
      </Text>
      <Text>
        Internal PR-A0 harness. It does not load model weights or create a chat
        provider. Token measurement explicitly downloads only the tokenizer for
        the pinned model revision.
      </Text>
      <Text>
        The WASM fallback button is a development affordance for machines with
        no WebGPU adapter. It proves the worker, bundling, and ONNX Runtime
        wiring only. WASM is not a supported inference path for this feature and
        produces no valid performance data.
      </Text>
      <div className={styles.actions}>
        <Button onClick={() => runSmoke(false)} disabled={busy}>
          Run WebGPU smoke test
        </Button>
        <Button onClick={() => runSmoke(true)} disabled={busy}>
          Run smoke test (allow WASM fallback)
        </Button>
        <Button onClick={runBudget} disabled={busy || !runtime}>
          Measure exact token budget
        </Button>
      </div>
      <Text>{status}</Text>
      <pre className={styles.output}>
        {JSON.stringify(
          {
            buildEnabled: __ENABLE_WEBGPU_LLM__,
            runtime,
            secureContext: window.isSecureContext,
            hostToolCount: tools.length,
            systemPromptCharacters: systemPrompt.length,
            smoke,
            budget,
            toolBudgetPass:
              budget && runtime
                ? budget.toolSchemaTokens <= runtime.maxToolSchemaTokens
                : null,
          },
          null,
          2,
        )}
      </pre>
    </main>
  );
}
